#include <Arduino.h>
#include <WiFi.h>
#include <HTTPClient.h>

const char* WIFI_SSID = "YOUR_SSID";
const char* WIFI_PASS = "YOUR_PASSWORD";
const char* TARGET_URL = "http://example.com/";
const unsigned long REQUEST_INTERVAL_MS = 10000;

void setup() {
  Serial.begin(115200);
  WiFi.begin(WIFI_SSID, WIFI_PASS);
  while (WiFi.status() != WL_CONNECTED) { delay(500); Serial.print("."); }
  Serial.println(); Serial.println("Wi-Fi bagli.");
}

void loop() {
  if (WiFi.status() == WL_CONNECTED) {
    HTTPClient http;
    http.begin(TARGET_URL);
    int code = http.GET();
    if (code > 0) {
      Serial.print("HTTP kodu: "); Serial.println(code);
      String payload = http.getString();
      Serial.println(payload);
    } else {
      Serial.print("Istek hatasi: "); Serial.println(code);
    }
    http.end();
  }
  delay(REQUEST_INTERVAL_MS);
}
